let rc11RefreshTimer=null;
function rc11ScheduleRefresh(){if(rc11RefreshTimer){clearInterval(rc11RefreshTimer);rc11RefreshTimer=null}const mode=rc11Settings().refreshMode;if(!session||mode==='live')return;const delay=mode==='daily'?86400000:3600000;rc11RefreshTimer=setInterval(()=>{if(session&&currentAccount())renderShell()},delay)}
window.addEventListener('storage',event=>{if(event.key==='rc_portal_v9'&&rc11Settings().refreshMode==='live'&&session){try{const next=JSON.parse(event.newValue||'null');if(next){store=next;session=store.session;renderShell()}}catch(e){}}});
function rc11SyncNavDefinitions(){
 const admin=[['admin-dashboard','⌂','navHome'],['clients','👥','navProfessionals'],['global-orders','◫','navOrders'],['invoices','▤','navInvoices'],['receivables','€','navReceivables'],['portfolio','◆','navPortfolio'],['loyalty','★','navLoyalty'],['referrals','↗','navReferrals'],['system-library','▧','navSystems'],['admin-messages','✉','navMessages'],['omnichannel','☎','navOmnichannel'],['admin-catalog','▥','navCatalog'],['regions','◎','navRegions'],['admin-import','⇅','navImports'],['admin-audit','≡','navAudit'],['admin-users','♟','navAdmins'],['admin-settings','⚙','navSettings'],['faq','?','navFaq']];
 const client=[['dashboard','⌂','navHome'],['calculator','▦','navCalculator'],['visualizer','◈','navVisualizer'],['cart','🛒','navCart'],['simulations','▤','navSimulations'],['orders','◫','navMyOrders'],['invoices','▥','navMyInvoices'],['catalog','▥','navClientCatalog'],['support','✉','navSupport'],['faq','?','navFaq']];
 RC101_ADMIN_TABS.splice(0,RC101_ADMIN_TABS.length,...admin.map(x=>[x[0],x[1],rc11T(x[2])]));RC101_CLIENT_TABS.splice(0,RC101_CLIENT_TABS.length,...client.map(x=>[x[0],x[1],rc11T(x[2])]));
}
adminNav=function(){rc11SyncNavDefinitions();return rc101OrderedTabs('admin')};
function rc11RegionNavConfig(regionId){const s=rc11Settings();s.navByRegion=s.navByRegion||{};s.navByRegion[regionId]=s.navByRegion[regionId]||{clientOrder:[],clientHidden:[]};return s.navByRegion[regionId]}
function rc11ApplyRegionalClientNav(items,regionId){const cfg=rc11RegionNavConfig(regionId),byId=Object.fromEntries(items.map(x=>[x[0],x])),order=[...(cfg.clientOrder||[]),...items.map(x=>x[0]).filter(id=>!(cfg.clientOrder||[]).includes(id))];return order.filter(id=>byId[id]&&!cfg.clientHidden.includes(id)).map(id=>byId[id])}
clientNav=function(){rc11SyncNavDefinitions();const c=currentClient(),regionId=c?.regionId||rc11AdminProfile()?.regionId||'CARIBBEAN',base=rc101OrderedTabs('client');return rc11ApplyRegionalClientNav(base,regionId).filter(([v])=>v!=='catalog'||c?.catalogAccess).filter(([v])=>v!=='visualizer'||visualizerAllowedV95())};

function rc11OpenClientEditor(id=''){
 const existing=(store.accounts||[]).find(a=>a.id===id),p=rc11AdminProfile();if(existing&&!rc11CanSeeClient(existing,p))return toast(rc11T('noPermission'));
 const regionId=existing?.regionId||(rc11IsGlobalHq(p)?'USA':p?.regionId||'CARIBBEAN'),territoryId=existing?.territoryId||(rc11IsGlobalHq(p)?'usa-indiana-hq':p?.territoryId||'car-saint-martin'),allowedRegions=rc11IsGlobalHq(p)?RC11_REGION_SEED:rc11IsCaribbeanHq(p)?RC11_REGION_SEED.filter(r=>r.id==='CARIBBEAN'):RC11_REGION_SEED.filter(r=>r.id===p?.regionId);
 showModal(`<div class="rc11-modal-wide"><h3>${esc(existing?rc11T('edit'):rc11T('addProfessional'))}</h3><p>${esc(rc11T('professionalsIntro'))}</p><div class="rc11-form-grid"><div class="field"><label>${esc(rc11T('company'))}</label><input id="rc11ClientCompany" value="${esc(existing?.company||'')}"></div><div class="field"><label>${esc(rc11T('contact'))}</label><input id="rc11ClientContact" value="${esc(rcClientName(existing||{}))}"></div><div class="field"><label>${esc(rc11T('email'))}</label><input id="rc11ClientEmail" type="email" value="${esc(existing?.email||'')}"></div><div class="field"><label>Phone</label><input id="rc11ClientPhone" value="${esc(existing?.phone||'')}"></div><div class="field"><label>${esc(rc11T('region'))}</label><select id="rc11ClientRegion">${allowedRegions.map(r=>`<option value="${r.id}" ${r.id===regionId?'selected':''}>${r.flag} ${esc(rc11RegionName(r.id))}</option>`).join('')}</select></div><div class="field"><label>${esc(rc11T('territory'))}</label><select id="rc11ClientTerritory">${rc11TerritoryOptions(regionId,territoryId)}</select></div><div class="field"><label>Category</label><select id="rc11ClientCategory">${categoryOptionsV91(existing?.category||'Professionnel / partenaire')}</select></div><div class="field"><label>Expertise</label><select id="rc11ClientExpertise">${expertiseOptionsV92(existing?.expertiseLevel||'Débutant')}</select></div><div class="field"><label>Price tier</label><select id="rc11ClientPriceTier"><option value="recommended" ${existing?.priceTier==='recommended'?'selected':''}>Reference</option><option value="large" ${existing?.priceTier==='large'?'selected':''}>Large project</option><option value="premium" ${existing?.priceTier==='premium'?'selected':''}>Premium</option></select></div><div class="field"><label>${esc(rc11T('environment'))}</label><select id="rc11ClientEnvironment"><option value="Interior" ${existing?.environment!=='Exterior'?'selected':''}>${esc(rc11T('interior'))}</option><option value="Exterior" ${existing?.environment==='Exterior'?'selected':''}>${esc(rc11T('exterior'))}</option></select></div><label class="permission-line"><input id="rc11ClientCatalogAccess" type="checkbox" ${existing?.catalogAccess?'checked':''}> Catalog access</label><label class="permission-line"><input id="rc11ClientVisualizer" type="checkbox" ${existing?.visualizerEnabled?'checked':''}> Floor visualizer</label></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" id="rc11SaveClient">${esc(rc11T('save'))}</button></div>${rc11SecurityBanner()}</div>`);
 if(!existing&&$('rc11ClientContact'))$('rc11ClientContact').value='';
 const syncTerritories=()=>{$('rc11ClientTerritory').innerHTML=rc11TerritoryOptions($('rc11ClientRegion').value,'')};$('rc11ClientRegion').onchange=syncTerritories;
 $('rc11SaveClient').onclick=()=>{const company=$('rc11ClientCompany').value.trim(),contact=$('rc11ClientContact').value.trim(),email=$('rc11ClientEmail').value.trim().toLowerCase(),newRegion=$('rc11ClientRegion').value,newTerritory=$('rc11ClientTerritory').value;if(!company||!contact)return toast(`${rc11T('company')} / ${rc11T('contact')}`);const candidate=existing||{id:rc11SafeId('client'),role:'client',active:true,createdAt:new Date().toISOString(),passwordHash:'',loginPending:true};candidate.regionId=newRegion;candidate.territoryId=newTerritory;if(!rc11CanManageClient(candidate,p)&&!rc11CanManageGlobal(p))return toast(rc11T('noPermission'));const parts=contact.split(/\s+/);Object.assign(candidate,{company,contact,firstName:parts.shift()||'',lastName:parts.join(' '),email,phone:$('rc11ClientPhone').value.trim(),category:$('rc11ClientCategory').value,expertiseLevel:$('rc11ClientExpertise').value,priceTier:$('rc11ClientPriceTier').value,environment:$('rc11ClientEnvironment').value,catalogAccess:$('rc11ClientCatalogAccess').checked,visualizerEnabled:$('rc11ClientVisualizer').checked,country:rc11Territory(newTerritory)?.name||'',city:rc11Territory(newTerritory)?.city||''});if(!existing){store.accounts.push(candidate);store.tenants[candidate.id]={cart:[],simulations:[],orders:[],documents:[],productChoices:{},packChoices:{},lineOverrides:{},customLines:{},visualSelection:null,messages:[],notifications:[]}}auditV9(existing?'Update professional':'Create professional','client:'+candidate.id,null,{regionId:newRegion,territoryId:newTerritory});saveStore();closeModal();renderShell();toast(rc11T('save'))};
}
function rc11DeleteClient(id){const c=store.accounts.find(a=>a.id===id);if(!c||!rc11CanManageClient(c))return toast(rc11T('noPermission'));const orders=store.tenants[id]?.orders||[];if(orders.length)return showModal(`<h3>${esc(rc11T('delete'))}</h3><p>This profile has ${orders.length} order(s) and cannot be deleted without breaking invoices and audit history. Deactivate it instead.</p><div class="toolbar"><button class="btn primary" id="rc11DeactivateInstead">${esc(rc11T('deactivate'))}</button><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button></div>`),$('rc11DeactivateInstead').onclick=()=>{c.active=false;saveStore();closeModal();renderShell()};showModal(`<h3>${esc(rc11T('delete'))} — ${esc(c.company)}</h3><p>This action removes the local prototype profile.</p><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn danger" id="rc11ConfirmDeleteClient">${esc(rc11T('delete'))}</button></div>`);$('rc11ConfirmDeleteClient').onclick=()=>{store.accounts=store.accounts.filter(a=>a.id!==id);delete store.tenants[id];auditV9('Delete professional','client:'+id,c,null);saveStore();closeModal();renderShell()}}

function rc11OpenAdminEditor(id=''){
 const p=rc11AdminProfile(),a=(store.adminProfiles||[]).find(x=>x.id===id);if(a&&!rc11CanManageAdmin(a,p)||!a&&!rc11CanManageGlobal(p))return toast(rc11T('noPermission'));const allowedRegions=rc11IsGlobalHq(p)?RC11_REGION_SEED:RC11_REGION_SEED.filter(r=>r.id==='CARIBBEAN'),regionId=a?.regionId||allowedRegions[0].id,territoryId=a?.territoryId||rc11Territories(regionId)[0]?.id||'';
 showModal(`<div class="rc11-modal-wide"><h3>${esc(a?rc11T('edit'):rc11T('addAdmin'))}</h3><div class="rc11-form-grid"><div class="field"><label>${esc(rc11T('contact'))}</label><input id="rc11AdminName" value="${esc(a?.name||'')}"></div><div class="field"><label>${esc(rc11T('email'))}</label><input id="rc11AdminEmail" type="email" value="${esc(a?.email||'')}"></div><div class="field"><label>${esc(rc11T('role'))}</label><select id="rc11AdminLevel"><option value="regional_admin" ${a?.level==='regional_admin'?'selected':''}>${esc(rc11T('regionalAdmin'))}</option><option value="read_only" ${a?.level==='read_only'?'selected':''}>${esc(rc11T('readOnly'))}</option>${rc11IsGlobalHq(p)?`<option value="global_hq" ${a?.level==='global_hq'?'selected':''}>${esc(rc11T('globalHq'))}</option>`:''}<option value="caribbean_hq" ${a?.level==='caribbean_hq'?'selected':''}>${esc(rc11T('caribbeanHq'))}</option></select></div><div class="field"><label>${esc(rc11T('region'))}</label><select id="rc11AdminRegion">${allowedRegions.map(r=>`<option value="${r.id}" ${r.id===regionId?'selected':''}>${esc(rc11RegionName(r.id))}</option>`).join('')}</select></div><div class="field"><label>${esc(rc11T('territory'))}</label><select id="rc11AdminTerritory">${rc11TerritoryOptions(regionId,territoryId)}</select></div><label class="permission-line"><input id="rc11AdminActive" type="checkbox" ${a?.active!==false?'checked':''}> ${esc(rc11T('active'))}</label></div><div class="rc11-security-banner"><b>${esc(rc11T('protectedSxm'))}</b>${esc(rc11T('coreOnly'))}</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" id="rc11SaveAdmin">${esc(rc11T('save'))}</button></div></div>`);
 $('rc11AdminRegion').onchange=()=>{$('rc11AdminTerritory').innerHTML=rc11TerritoryOptions($('rc11AdminRegion').value,'')};
 $('rc11SaveAdmin').onclick=()=>{const name=$('rc11AdminName').value.trim(),level=$('rc11AdminLevel').value;let region=$('rc11AdminRegion').value,territory=$('rc11AdminTerritory').value;if(!name)return toast(rc11T('contact'));if(level==='global_hq'){if(!rc11IsGlobalHq(p))return toast(rc11T('noPermission'));region='USA';territory='usa-indiana-hq'}if(level==='caribbean_hq'||territory==='car-saint-martin'){if(!RC11_CORE_SXM_NAMES.map(rc11NormalizeName).includes(rc11NormalizeName(name)))return toast(rc11T('coreOnly'));region='CARIBBEAN';territory='car-saint-martin'}const target=a||{id:rc11SafeId('admin'),createdAt:new Date().toISOString()};Object.assign(target,{name,email:$('rc11AdminEmail').value.trim().toLowerCase(),level,regionId:region,territoryId:territory,active:$('rc11AdminActive').checked,protected:level==='global_hq'||level==='caribbean_hq'});if(!a)store.adminProfiles.push(target);auditV9(a?'Update administrator':'Create administrator','admin:'+target.id,null,{level,region,territory});saveStore();closeModal();renderShell()};
}
function rc11DeleteAdmin(id){const p=rc11AdminProfile(),a=store.adminProfiles.find(x=>x.id===id);if(!a||!rc11CanManageAdmin(a,p)||p?.id===id)return toast(rc11T('noPermission'));showModal(`<h3>${esc(rc11T('delete'))} — ${esc(a.name)}</h3><p>${esc(rc11T('details'))}</p><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn danger" id="rc11ConfirmDeleteAdmin">${esc(rc11T('delete'))}</button></div>`);$('rc11ConfirmDeleteAdmin').onclick=()=>{store.adminProfiles=store.adminProfiles.filter(x=>x.id!==id);auditV9('Delete administrator','admin:'+id,a,null);saveStore();closeModal();renderShell()}}

function rc11OpenTerritoryEditor(){if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));showModal(`<h3>${esc(rc11T('addTerritory'))}</h3><div class="rc11-form-grid"><div class="field"><label>${esc(rc11T('region'))}</label><select id="rc11TerritoryRegion">${rc11RegionOptions('CARIBBEAN')}</select></div><div class="field"><label>${esc(rc11T('country'))}</label><input id="rc11TerritoryName"></div><div class="field"><label>${esc(rc11T('city'))}</label><input id="rc11TerritoryCity"></div><div class="field"><label>${esc(rc11T('code'))}</label><input id="rc11TerritoryCode" maxlength="6"></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" id="rc11SaveTerritory">${esc(rc11T('save'))}</button></div>`);$('rc11SaveTerritory').onclick=()=>{const name=$('rc11TerritoryName').value.trim(),regionId=$('rc11TerritoryRegion').value,code=$('rc11TerritoryCode').value.trim().toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6);if(!name||!code)return toast(`${rc11T('country')} / ${rc11T('code')}`);rc11Settings().customTerritories.push({id:rc11SafeId('territory'),code,name,city:$('rc11TerritoryCity').value.trim(),regionId,custom:true});saveStore();closeModal();renderShell()}}
function rc11DeleteTerritory(id){if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));const t=rc11Territory(id);if(!t?.custom)return toast(rc11T('noPermission'));if((store.accounts||[]).some(a=>a.territoryId===id))return toast('This territory is assigned to an account and cannot be deleted.');rc11Settings().customTerritories=rc11Settings().customTerritories.filter(x=>x.id!==id);saveStore();renderShell()}

function rc11OpenSystemEditor(id=''){
 if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));const sys=SYSTEMS.find(s=>s.id===id),meta=sys?rc11SystemMetaV11(sys):null,templates=SYSTEMS.filter(s=>!s.rc11Archived);showModal(`<div class="rc11-modal-wide"><h3>${esc(sys?rc11T('edit'):rc11T('addSystem'))}</h3><div class="rc11-form-grid"><div class="field full"><label>${esc(rc11T('system'))}</label><input id="rc11SystemName" value="${esc(sys?.name||'')}"></div>${sys?'':`<div class="field full"><label>${esc(rc11T('template'))}</label><select id="rc11SystemTemplate">${templates.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div>`}<div class="field full"><label>${esc(rc11T('usage'))}</label><textarea id="rc11SystemDescription" rows="3">${esc(meta?.description||'')}</textarea></div><div class="field"><label>${esc(rc11T('environment'))}</label><select id="rc11SystemEnvironment"><option value="Interior" ${meta?.environment==='Interior'?'selected':''}>${esc(rc11T('interior'))}</option><option value="Exterior" ${meta?.environment==='Exterior'?'selected':''}>${esc(rc11T('exterior'))}</option><option value="Interior / Exterior" ${meta?.environment?.includes('Interior / Exterior')?'selected':''}>Interior / Exterior</option></select></div><div class="field"><label>${esc(rc11T('photo'))} — 5 MB max</label><input id="rc11SystemPhoto" type="file" accept="image/*"></div><div class="field full"><label>${esc(rc11T('layers'))} — one line per layer</label><textarea id="rc11SystemLayers" rows="9">${esc((meta?.layers||[]).join('\n'))}</textarea></div><label class="permission-line"><input id="rc11SystemPublished" type="checkbox" ${meta?.published!==false?'checked':''}> ${esc(rc11T('published'))}</label></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" id="rc11SaveSystem">${esc(rc11T('save'))}</button></div></div>`);
 $('rc11SaveSystem').onclick=async()=>{const name=$('rc11SystemName').value.trim();if(!name)return toast(rc11T('system'));let target=sys;if(!target){const template=SYSTEMS.find(s=>s.id===$('rc11SystemTemplate').value)||SYSTEMS[0],newId='custom-'+name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,34)+'-'+Date.now().toString(36);target={...JSON.parse(JSON.stringify(template)),id:newId,name};SYSTEMS.push(target);rc11Settings().customSystems.push(JSON.parse(JSON.stringify(target)));rc11Settings().systemOrder.push(newId)}target.name=name;const m=rc101SystemMeta(target.id);m.description=$('rc11SystemDescription').value.trim();m.environment=$('rc11SystemEnvironment').value;m.published=$('rc11SystemPublished').checked;const layers=$('rc11SystemLayers').value.split(/\n/).map(x=>x.trim()).filter(Boolean);if(layers.length)m.layers=layers;const file=$('rc11SystemPhoto').files[0];if(file){if(file.size>5*1024*1024)return toast('Photo exceeds 5 MB.');m.image=await rc101CompressImage(file)}rc101ApplySystemLayers();const idx=rc11Settings().customSystems.findIndex(x=>x.id===target.id);if(idx>=0)rc11Settings().customSystems[idx]=JSON.parse(JSON.stringify(target));saveStore();closeModal();renderShell();toast(rc11T('save'))};
}
function rc11ToggleSystem(id){if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));const s=rc11Settings(),i=s.archivedSystems.indexOf(id);if(i>=0)s.archivedSystems.splice(i,1);else s.archivedSystems.push(id);const sys=SYSTEMS.find(x=>x.id===id);if(sys)sys.rc11Archived=i<0;saveStore();renderShell()}
function rc11DeleteSystem(id){
 if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));
 const s=rc11Settings(),sys=SYSTEMS.find(x=>x.id===id),isCustom=s.customSystems.some(x=>x.id===id);if(!sys)return;
 if(!isCustom)return rc11ToggleSystem(id);
 const used=rc11OrdersFor((store.accounts||[]).filter(a=>a.role==='client')).some(x=>x.order.systemId===id||(x.order.items||[]).some(i=>i.systemId===id));
 if(used)return toast('This system is referenced by an order and can only be archived.');
 showModal(`<h3>${esc(rc11T('delete'))} — ${esc(sys.name)}</h3><p>This custom system will be removed from the library and calculator.</p><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn danger" id="rc11ConfirmDeleteSystem">${esc(rc11T('delete'))}</button></div>`);
 $('rc11ConfirmDeleteSystem').onclick=()=>{s.customSystems=s.customSystems.filter(x=>x.id!==id);s.systemOrder=s.systemOrder.filter(x=>x!==id);s.archivedSystems=s.archivedSystems.filter(x=>x!==id);delete store.settings.systemLibrary?.[id];const index=SYSTEMS.findIndex(x=>x.id===id);if(index>=0)SYSTEMS.splice(index,1);auditV9('Delete custom system','system:'+id,sys,null);saveStore();closeModal();renderShell()};
}
function rc11BindSystemDrag(){if(!rc11CanManageGlobal())return;let dragged='';document.querySelectorAll('[data-rc11-system]').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card.dataset.rc11System;card.classList.add('dragging')});card.addEventListener('dragend',()=>{card.classList.remove('dragging');dragged=''});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();const target=card.dataset.rc11System;if(!dragged||dragged===target)return;const order=rc11Settings().systemOrder,i=order.indexOf(dragged),j=order.indexOf(target);if(i<0||j<0)return;order.splice(j,0,order.splice(i,1)[0]);rc11ApplyCustomSystems();saveStore();renderShell()})})}

function rc11FindInvoice(number){return rc11AllInvoices(isAdmin()?rc11VisibleClients():[currentClient()]).find(x=>x.invoice.number===number)}
function rc11OpenInvoice(number){const x=rc11FindInvoice(number);if(!x)return toast(rc11T('noPermission'));const v=x.invoice,items=v.items||[];showModal(`<article class="rc11-invoice-sheet"><header><div><small>${esc(rc11T('invoiceNo'))}</small><h2>${esc(v.number)}</h2><p>${esc(rc11T('issuedOn'))} ${rc11Date(v.issuedAt)}</p></div><div class="invoice-brand"><b>RENOVO CRETE</b><span>${esc(rc11RegionName(v.regionId))} · ${esc(rc11TerritoryLabel(v.territoryId))}</span><br><small>${esc(rc11T('paymentConfirmed'))}</small></div></header><div class="rc11-invoice-parties"><section><small>${esc(rc11T('billTo'))}</small><h3>${esc(v.company)}</h3><p>${esc(v.clientName)}<br>${esc(v.address||'')}<br>${esc(v.email||'')}</p></section><section><small>${esc(rc11T('orderNo'))}</small><h3>${esc(v.orderNumber)}</h3><p>${esc(v.project||'')}<br>${esc(v.systemName)}<br>${esc(v.country)}</p></section></div><div class="table-wrap"><table class="rc11-table"><thead><tr><th>${esc(rc11T('description'))}</th><th>${esc(rc11T('pack'))}</th><th>${esc(rc11T('quantity'))}</th><th>${esc(rc11T('unitPrice'))}</th><th>${esc(rc11T('total'))}</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.product||i.systemName||v.systemName)}</td><td>${esc(i.pack||'—')}</td><td>${num.format(Number(i.quantity||0))}</td><td>${rc11Money(i.unitPriceEUR||0)}</td><td><b>${rc11Money(i.totalEUR||0)}</b></td></tr>`).join('')}</tbody></table></div><div class="rc11-invoice-total"><div><span>${esc(rc11T('total'))} EUR</span><b>${rc11Money(v.totalEUR)}</b></div>${v.totalUSD?`<div><span>${esc(rc11T('total'))} USD</span><b>${rc11Money(v.totalUSD,'USD')}</b></div>`:''}<div class="grand"><span>${esc(rc11T('paid'))}</span><b>${rc11Money(v.totalEUR)}</b></div></div><div class="rc11-security-banner">${esc(rc11T('taxNote'))}</div><div class="toolbar rc11-no-print"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" onclick="window.print()">${esc(rc11T('downloadPrint'))}</button></div></article>`)}

function rc11ApplyProfessionalFilters(){const q=($('rc11ProfessionalSearch')?.value||'').toLowerCase(),region=$('rc11ProfessionalRegion')?.value||'',territory=$('rc11ProfessionalTerritory')?.value||'',tier=$('rc11ProfessionalTier')?.value||'',active=$('rc11ProfessionalActive')?.value||'';let n=0;document.querySelectorAll('[data-rc11-professional]').forEach(card=>{const ok=(!q||card.dataset.search.includes(q))&&(!region||card.dataset.region===region)&&(!territory||card.dataset.territory===territory)&&(!tier||card.dataset.tier===tier)&&(!active||card.dataset.active===active);card.style.display=ok?'':'none';if(ok){n++;card.querySelector(':scope > .rc11-number').textContent=String(n).padStart(3,'0')}})}
function rc11ApplyOrderFilters(){const q=($('rc11OrderSearch')?.value||'').toLowerCase(),region=$('rc11OrderRegion')?.value||'',territory=$('rc11OrderTerritory')?.value||'',system=$('rc11OrderSystem')?.value||'',status=$('rc11OrderStatus')?.value||'',payment=$('rc11OrderPayment')?.value||'',environment=$('rc11OrderEnvironment')?.value||'',min=Number($('rc11OrderMin')?.value||0),start=$('rc11OrderStart')?.value?new Date($('rc11OrderStart').value+'T00:00:00').getTime():-Infinity,end=$('rc11OrderEnd')?.value?new Date($('rc11OrderEnd').value+'T23:59:59').getTime():Infinity;let n=0;document.querySelectorAll('[data-rc11-order]').forEach(card=>{const ok=(!q||card.dataset.search.includes(q))&&(!region||card.dataset.region===region)&&(!territory||card.dataset.territory===territory)&&(!system||card.dataset.system===system)&&(!status||card.dataset.status===status)&&(!payment||card.dataset.payment===payment)&&(!environment||card.dataset.environment===environment)&&Number(card.dataset.amount)>=min&&Number(card.dataset.time)>=start&&Number(card.dataset.time)<=end;card.style.display=ok?'':'none';if(ok){n++;card.querySelector(':scope > .rc11-number').textContent=String(n).padStart(3,'0')}})}
function rc11ApplyInvoiceFilters(){const q=($('rc11InvoiceSearch')?.value||'').toLowerCase(),client=($('rc11InvoiceClient')?.value||'').toLowerCase(),region=$('rc11InvoiceRegion')?.value||'',country=$('rc11InvoiceCountry')?.value||'',system=$('rc11InvoiceSystem')?.value||'',environment=$('rc11InvoiceEnvironment')?.value||'',min=Number($('rc11InvoiceMin')?.value||0),start=$('rc11InvoiceStart')?.value?new Date($('rc11InvoiceStart').value+'T00:00:00').getTime():-Infinity,end=$('rc11InvoiceEnd')?.value?new Date($('rc11InvoiceEnd').value+'T23:59:59').getTime():Infinity;let n=0;document.querySelectorAll('[data-rc11-invoice-card]').forEach(card=>{const ok=(!q||card.dataset.search.includes(q))&&(!client||card.dataset.client.includes(client))&&(!region||card.dataset.region===region)&&(!country||card.dataset.country===country)&&(!system||card.dataset.system===system)&&(!environment||card.dataset.environment===environment)&&Number(card.dataset.amount)>=min&&Number(card.dataset.time)>=start&&Number(card.dataset.time)<=end;card.style.display=ok?'':'none';if(ok){n++;const badge=card.querySelector('.rc11-number');if(badge)badge.textContent=String(n).padStart(3,'0')}})}
function rc11BindViewSwitches(){document.querySelectorAll('[data-rc11-view-kind]').forEach(box=>box.querySelectorAll('[data-rc11-view]').forEach(btn=>btn.onclick=()=>{let mode=btn.dataset.rc11View;if(box.dataset.rc11ViewKind==='invoices'&&mode==='medium')mode='cards';rc11Settings().viewModes[box.dataset.rc11ViewKind]=mode;saveStore();renderShell()}))}

function rc11SaveCatalogRow(button){if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));const row=button.closest('tr'),id=button.dataset.rc11SavePrice,tier=rc11Settings().catalogTier||'recommended',values={};row.querySelectorAll('[data-price]').forEach(i=>values[i.dataset.price]=Math.max(0,Number(i.value)||0));store.catalogOverrides[id]=store.catalogOverrides[id]||{};store.catalogOverrides[id].rc11Prices=store.catalogOverrides[id].rc11Prices||{};store.catalogOverrides[id].rc11Prices[tier]=values;store.catalogOverrides[id].prices=store.catalogOverrides[id].prices||{};store.catalogOverrides[id].prices[tier]={...(store.catalogOverrides[id].prices[tier]||{}),baseUSD:values.costUSD,resaleUSD:values.resaleUSD,eur:values.resaleEUR};auditV9('Update ECS and resale pricing','catalog:'+id,null,{tier,...values});saveStore();toast(rc11T('priceSaved'))}
async function rc11RefreshMarketRate(){const btn=$('rc11RefreshMarketRate');if(btn)btn.disabled=true;try{const res=await fetch('https://api.frankfurter.dev/v2/rate/EUR/USD',{headers:{Accept:'application/json'}});if(!res.ok)throw new Error(`HTTP ${res.status}`);const data=await res.json(),rate=Number(data.rate);if(!Number.isFinite(rate))throw new Error('Invalid rate');rc11Settings().marketRate=rate;rc11Settings().marketRateUpdated=new Date().toISOString();saveStore();$('rc11MarketRate').textContent=rate.toFixed(4);$('rc11MarketUpdated').textContent=rc11Date(rc11Settings().marketRateUpdated,true);toast(rc11T('updated'))}catch(e){toast('Market rate unavailable — keep the manual rate.')}finally{if(btn)btn.disabled=false}}

function rc11OpenChannel(channel){const id=$('rc11OmniRecipient')?.value,c=store.accounts.find(a=>a.id===id);if(!c)return toast(rc11T('recipient'));const subject=$('rc11OmniSubject')?.value.trim()||'RENOVO CRETE',message=$('rc11OmniMessage')?.value.trim();if(!message)return toast(rc11T('message'));const label=channel==='email'?rc11T('sendEmail'):channel==='whatsapp'?rc11T('sendWhatsapp'):channel==='sms'?rc11T('sendSms'):rc11T('call');showModal(`<h3>${esc(label)} — ${esc(c.company)}</h3><p><b>${esc(rcClientName(c))}</b><br>${esc(channel==='email'?c.email:c.phone||'')}</p><div class="notice">${esc(subject)}<br><br>${esc(message)}</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${esc(rc11T('cancel'))}</button><button class="btn primary" id="rc11ConfirmChannel">${esc(label)}</button></div>`);$('rc11ConfirmChannel').onclick=()=>rc11DispatchChannel(channel,c,subject,message)}
async function rc11DispatchChannel(channel,c,subject,message){const i=rc11Settings().integrations,phone=String(c.phone||'').replace(/\D/g,''),email=c.email||'',endpoint=channel==='email'?i.brevoWebhook:['sms','whatsapp'].includes(channel)?i.twilioWebhook:'';if(endpoint){try{const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel,clientId:c.id,to:channel==='email'?email:phone,subject,message})});if(!res.ok)throw new Error(`HTTP ${res.status}`);closeModal();toast(rc11T('connected'));return}catch(e){toast('Secure connector unavailable — opening the device channel.')}}if(channel==='email')location.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`;else if(channel==='whatsapp')window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener');else if(channel==='sms')location.href=`sms:${phone}?body=${encodeURIComponent(message)}`;else location.href=`tel:${phone}`;closeModal()}

