function rc11RegionalTabPanel(){const p=rc11AdminProfile(),regionId=rc11SettingsTargetRegion(),cfg=rc11RegionNavConfig(regionId),byId=Object.fromEntries(RC101_CLIENT_TABS.map(x=>[x[0],x])),order=[...(cfg.clientOrder||[]),...RC101_CLIENT_TABS.map(x=>x[0]).filter(id=>!(cfg.clientOrder||[]).includes(id))];return`<section class="rc11-panel" style="margin-bottom:14px"><div class="rc11-section-head"><div><span class="eyebrow">REGIONAL CLIENT INTERFACE</span><h3>${esc(rc11RegionName(regionId))}</h3><p>Configure only the client/subcontractor interface for this region.</p></div>${rc11CanManageGlobal(p)?`<select id="rc11SettingsRegion">${RC11_REGION_SEED.map(r=>`<option value="${r.id}" ${r.id===regionId?'selected':''}>${esc(rc11RegionName(r.id))}</option>`).join('')}</select>`:''}</div><div class="rc101-tab-list">${order.map((id,index)=>{const tab=byId[id],hidden=cfg.clientHidden.includes(id);return`<div class="rc101-tab-row ${hidden?'hidden-tab':''}"><span><b>${esc(tab?.[2]||id)}</b><br><small>${esc(id)}</small></span><span><button class="btn secondary small" data-rc11-region-tab-up="${id}" ${index===0?'disabled':''}>↑</button><button class="btn secondary small" data-rc11-region-tab-down="${id}" ${index===order.length-1?'disabled':''}>↓</button><button class="btn ${hidden?'primary':'secondary'} small" data-rc11-region-tab-toggle="${id}">${hidden?'Show':'Hide'}</button></span></div>`}).join('')}</div><div class="rc11-security-banner">USA Headquarters and the four Saint-Martin Caribbean HQ administrators may select another region. Other administrators edit only their own regional client interface.</div></section>`}
