function rc11EnhanceTopbar(){const actions=document.querySelector('.top-actions');if(!actions)return;actions.querySelector('#rc11LanguageSwitch')?.remove();actions.querySelector('#rc11ScopeControl')?.remove();actions.querySelector('#rc11RegionLock')?.remove();const lang=document.createElement('div');lang.id='rc11LanguageSwitch';lang.className='rc11-language-switch';lang.setAttribute('aria-label','Language');lang.innerHTML=`<button data-lang="en" class="${rc11Lang()==='en'?'active':''}" title="English">🇬🇧</button><button data-lang="fr" class="${rc11Lang()==='fr'?'active':''}" title="Français">🇫🇷</button><button data-lang="es" class="${rc11Lang()==='es'?'active':''}" title="Español">🇪🇸</button>`;const bell=actions.querySelector('#globalAlertV96');actions.insertBefore(lang,bell||actions.firstChild);lang.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{rc11Settings().language=b.dataset.lang;saveStore();rc11ApplyAuthLanguage();renderShell()});const p=rc11AdminProfile();if(isAdmin()&&!currentClient()){if(rc11CanManageGlobal(p)){const scope=document.createElement('label');scope.id='rc11ScopeControl';scope.className='rc11-scope-control';scope.innerHTML=`<span>${esc(rc11T('regionalScope'))}</span><select>${rc11RegionOptions(rc11Settings().scopeRegion,true)}</select>`;actions.insertBefore(scope,actions.querySelector('.mode'));scope.querySelector('select').onchange=e=>{rc11Settings().scopeRegion=e.target.value;saveStore();renderShell()}}else{const lock=document.createElement('span');lock.id='rc11RegionLock';lock.className='rc11-region-lock';lock.textContent=`⌾ ${rc11RegionName(p?.regionId)}`;actions.insertBefore(lock,actions.querySelector('.mode'))}}const logout=$('logoutButton'),back=$('backAdminButton');if(logout)logout.textContent=rc11T('logout');if(back)back.textContent=rc11T('backAdmin');if($('modeLabel'))$('modeLabel').textContent=currentClient()?(isAdmin()?`${rc11T('adminDemo')} · ${currentClient().company}`:rc11T('professionalDemo')):rc11RoleLabel(p?.level)}

function rc11BindController(){
 rc11BindViewSwitches();
 document.querySelectorAll('[data-rc11-page]').forEach(b=>b.onclick=()=>{rc11RecentPage=Number(b.dataset.rc11Page)||1;renderShell()});
 document.querySelectorAll('[data-rc11-order-open]').forEach(b=>b.onclick=()=>{const[tid,i]=b.dataset.rc11OrderOpen.split('|');rcShowOrderDetail(tid,Number(i))});
 document.querySelectorAll('[data-rc11-client-order]').forEach(b=>b.onclick=()=>{const sorted=(tenantData().orders||[]).slice().sort((a,c)=>new Date(c.createdAt)-new Date(a.createdAt)),o=sorted[Number(b.dataset.rc11ClientOrder)];if(o)showModal(orderDetailV96(o,false,effectiveClientId(),tenantData().orders.indexOf(o)))});
 document.querySelectorAll('[data-rc11-invoice]').forEach(b=>b.onclick=()=>rc11OpenInvoice(b.dataset.rc11Invoice));
 document.querySelectorAll('[data-rc11-edit-client]').forEach(b=>b.onclick=()=>rc11OpenClientEditor(b.dataset.rc11EditClient));
 document.querySelectorAll('[data-rc11-toggle-client]').forEach(b=>b.onclick=()=>{const c=store.accounts.find(a=>a.id===b.dataset.rc11ToggleClient);if(c&&rc11CanManageClient(c)){c.active=!c.active;saveStore();renderShell()}});
 document.querySelectorAll('[data-rc11-delete-client]').forEach(b=>b.onclick=()=>rc11DeleteClient(b.dataset.rc11DeleteClient));
 $('rc11AddProfessional')?.addEventListener('click',()=>rc11OpenClientEditor());
 if(currentView==='clients'){['rc11ProfessionalSearch','rc11ProfessionalRegion','rc11ProfessionalTerritory','rc11ProfessionalTier','rc11ProfessionalActive'].forEach(id=>$(id)?.addEventListener(id==='rc11ProfessionalSearch'?'input':'change',rc11ApplyProfessionalFilters))}
 if(currentView==='global-orders'||currentView==='orders'){['rc11OrderSearch','rc11OrderRegion','rc11OrderTerritory','rc11OrderSystem','rc11OrderStatus','rc11OrderPayment','rc11OrderEnvironment','rc11OrderStart','rc11OrderEnd','rc11OrderMin'].forEach(id=>$(id)?.addEventListener(id==='rc11OrderSearch'||id==='rc11OrderMin'?'input':'change',rc11ApplyOrderFilters));$('rc11ResetOrders')?.addEventListener('click',()=>renderShell())}
 document.querySelectorAll('[data-rc11-order-status]').forEach(s=>s.onchange=()=>{const[tid,i]=s.dataset.rc11OrderStatus.split('|'),o=store.tenants[tid]?.orders?.[Number(i)];if(!o)return;const old=o.status;o.status=s.value;o.updatedAt=new Date().toISOString();o.statusHistory=o.statusHistory||[];o.statusHistory.unshift({status:o.status,at:o.updatedAt,author:rc11AdminProfile()?.name||'Administrator'});auditV9('Update order status','order:'+o.id,old,o.status);saveStore();renderShell()});
 document.querySelectorAll('[data-rc11-payment-status]').forEach(s=>s.onchange=()=>{const[tid,i]=s.dataset.rc11PaymentStatus.split('|'),o=store.tenants[tid]?.orders?.[Number(i)],c=store.accounts.find(a=>a.id===tid);if(!o||!c)return;if(o.invoice?.number&&s.value!=='Payé'&&s.value!=='Remboursé'){s.value=o.paymentStatus;return toast('A numbered invoice is immutable. Use a refund / credit-note workflow.')}const old=o.paymentStatus;o.paymentStatus=s.value;o.updatedAt=new Date().toISOString();if(s.value==='Payé'){o.paidAmount=Number(o.totalEUR||0);o.paidAt=o.paidAt||o.updatedAt;rc11EnsureInvoice(o,c)}auditV9('Update payment status','order:'+o.id,old,o.paymentStatus);saveStore();renderShell()});
 if(currentView==='invoices'){['rc11InvoiceSearch','rc11InvoiceClient','rc11InvoiceRegion','rc11InvoiceCountry','rc11InvoiceSystem','rc11InvoiceEnvironment','rc11InvoiceStart','rc11InvoiceEnd','rc11InvoiceMin'].forEach(id=>$(id)?.addEventListener(['rc11InvoiceSearch','rc11InvoiceClient','rc11InvoiceMin'].includes(id)?'input':'change',rc11ApplyInvoiceFilters));$('rc11ResetInvoices')?.addEventListener('click',()=>renderShell())}
 $('rc11LoyaltyYear')?.addEventListener('change',e=>{rc11Settings().loyaltyYear=Number(e.target.value);saveStore();renderShell()});$('rc11SaveThresholds')?.addEventListener('click',()=>{const p=Number($('rc11ThresholdPremium').value),pr=Number($('rc11ThresholdPrestige').value),e=Number($('rc11ThresholdElite').value);if(!(p>=100000&&pr>=250000&&e>=500000&&pr>p&&e>pr))return toast('Minimum levels: €100,000 / €250,000 / €500,000.');Object.assign(store.settings.loyaltyThresholds,{premium:p,prestige:pr,elite:e});saveStore();renderShell();toast(rc11T('save'))});
 $('rc11AddSystem')?.addEventListener('click',()=>rc11OpenSystemEditor());document.querySelectorAll('[data-rc11-edit-system]').forEach(b=>b.onclick=()=>rc11OpenSystemEditor(b.dataset.rc11EditSystem));document.querySelectorAll('[data-rc11-archive-system]').forEach(b=>b.onclick=()=>rc11ToggleSystem(b.dataset.rc11ArchiveSystem));document.querySelectorAll('[data-rc-use-system]').forEach(b=>b.onclick=()=>{const s=SYSTEMS.find(x=>x.id===b.dataset.rcUseSystem);if(s?.rc11Archived)return toast(rc11T('archive'));form.systemId=b.dataset.rcUseSystem;result=null;go('calculator')});if(currentView==='system-library'){document.querySelectorAll('[data-rc11-system]').forEach(card=>{const id=card.dataset.rc11System;if(rc11Settings().customSystems.some(x=>x.id===id)){const bar=card.querySelector('.toolbar');if(bar&&!bar.querySelector('[data-rc11-delete-system]'))bar.insertAdjacentHTML('beforeend',`<button class="btn danger small" data-rc11-delete-system="${esc(id)}">${esc(rc11T('delete'))}</button>`)} });document.querySelectorAll('[data-rc11-delete-system]').forEach(b=>b.onclick=()=>rc11DeleteSystem(b.dataset.rc11DeleteSystem));rc11BindSystemDrag()}
 if(currentView==='admin-catalog'){const filter=()=>{const q=($('rc11CatalogSearch')?.value||'').toLowerCase(),f=$('rc11CatalogFamily')?.value||'';let n=0;document.querySelectorAll('[data-rc11-catalog-row]').forEach(row=>{const ok=(!q||row.dataset.search.includes(q))&&(!f||row.dataset.family===f);row.style.display=ok?'':'none';if(ok){n++;row.querySelector('.rc11-number').textContent=n}})};$('rc11CatalogSearch')?.addEventListener('input',filter);$('rc11CatalogFamily')?.addEventListener('change',filter);$('rc11CatalogTier')?.addEventListener('change',e=>{rc11Settings().catalogTier=e.target.value;saveStore();renderShell()});document.querySelectorAll('[data-rc11-save-price]').forEach(b=>b.onclick=()=>rc11SaveCatalogRow(b));$('rc11ApplyRate')?.addEventListener('click',()=>{if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));const r=Number($('rc11ManualRate').value);if(!Number.isFinite(r)||r<=0)return toast('Invalid exchange rate.');rc11Settings().exchangeRate=r;saveStore();renderShell()});$('rc11RefreshMarketRate')?.addEventListener('click',rc11RefreshMarketRate);if(!rc11CanManageGlobal()){document.querySelectorAll('[data-price]').forEach(i=>i.disabled=true);document.querySelectorAll('[data-rc11-save-price]').forEach(b=>b.disabled=true);if($('rc11ManualRate'))$('rc11ManualRate').disabled=true;if($('rc11ApplyRate'))$('rc11ApplyRate').disabled=true}}
 $('rc11AddTerritory')?.addEventListener('click',rc11OpenTerritoryEditor);document.querySelectorAll('[data-rc11-delete-territory]').forEach(b=>b.onclick=()=>rc11DeleteTerritory(b.dataset.rc11DeleteTerritory));document.querySelectorAll('[data-rc11-scope-region]').forEach(b=>b.onclick=()=>{rc11Settings().scopeRegion=b.dataset.rc11ScopeRegion;saveStore();renderShell()});if($('rc11RefreshMode')&&!$('rc11RefreshMode').querySelector('[value="live"]'))$('rc11RefreshMode').insertAdjacentHTML('afterbegin',`<option value="live" ${rc11Settings().refreshMode==='live'?'selected':''}>${esc(rc11T('refreshLive'))}</option>`);$('rc11RefreshMode')?.addEventListener('change',e=>{rc11Settings().refreshMode=e.target.value;saveStore();renderShell()});
 $('rc11AddAdmin')?.addEventListener('click',()=>rc11OpenAdminEditor());document.querySelectorAll('[data-rc11-edit-admin]').forEach(b=>b.onclick=()=>rc11OpenAdminEditor(b.dataset.rc11EditAdmin));document.querySelectorAll('[data-rc11-delete-admin]').forEach(b=>b.onclick=()=>rc11DeleteAdmin(b.dataset.rc11DeleteAdmin));
 if(currentView==='admin-settings'){
  $('rc11SettingsRegion')?.addEventListener('change',e=>{rc11Settings().settingsTargetRegion=e.target.value;saveStore();renderShell()});
  const move=(id,delta)=>{const cfg=rc11RegionNavConfig(rc11SettingsTargetRegion()),base=RC101_CLIENT_TABS.map(x=>x[0]),order=[...(cfg.clientOrder||[]),...base.filter(x=>!(cfg.clientOrder||[]).includes(x))],i=order.indexOf(id),j=i+delta;if(i<0||j<0||j>=order.length)return;[order[i],order[j]]=[order[j],order[i]];cfg.clientOrder=order;saveStore();renderShell()};
  document.querySelectorAll('[data-rc11-region-tab-up]').forEach(b=>b.onclick=()=>move(b.dataset.rc11RegionTabUp,-1));document.querySelectorAll('[data-rc11-region-tab-down]').forEach(b=>b.onclick=()=>move(b.dataset.rc11RegionTabDown,1));document.querySelectorAll('[data-rc11-region-tab-toggle]').forEach(b=>b.onclick=()=>{const cfg=rc11RegionNavConfig(rc11SettingsTargetRegion()),id=b.dataset.rc11RegionTabToggle,i=cfg.clientHidden.indexOf(id);if(i>=0)cfg.clientHidden.splice(i,1);else cfg.clientHidden.push(id);saveStore();renderShell()});
  if(!rc11CanManageGlobal()){document.querySelectorAll('[data-rc101-tab-up],[data-rc101-tab-down],[data-rc101-tab-toggle],#rc101ResetTabs').forEach(b=>b.disabled=true)}
 }
 document.querySelectorAll('[data-rc11-channel]').forEach(b=>b.onclick=()=>rc11OpenChannel(b.dataset.rc11Channel));$('rc11SaveIntegrations')?.addEventListener('click',()=>{if(!rc11CanManageGlobal())return toast(rc11T('noPermission'));Object.assign(rc11Settings().integrations,{brevoWebhook:$('rc11BrevoWebhook').value.trim(),twilioWebhook:$('rc11TwilioWebhook').value.trim(),hubspotWebhook:$('rc11HubspotWebhook').value.trim(),whatsappNumber:$('rc11WhatsappNumber').value.trim(),supportEmail:$('rc11SupportEmail').value.trim(),supportPhone:$('rc11SupportPhone').value.trim()});saveStore();renderShell();toast(rc11T('saveConnections'))});if(currentView==='omnichannel'&&!rc11CanManageGlobal()){['rc11BrevoWebhook','rc11TwilioWebhook','rc11HubspotWebhook','rc11WhatsappNumber','rc11SupportEmail','rc11SupportPhone','rc11SaveIntegrations'].forEach(id=>{if($(id))$(id).disabled=true})}
}

const rc11BaseRenderContent=renderContent;
renderContent=function(){const extra={receivables:renderReceivablesV11,portfolio:renderPortfolioV11,loyalty:renderLoyaltyV11,'system-library':renderSystemLibraryV11,'admin-catalog':renderAdminCatalogV11,invoices:renderInvoicesV11,regions:renderRegionsV11,'admin-users':renderAdministratorsV11,omnichannel:renderOmnichannelV11};if(extra[currentView]){$('content').innerHTML=extra[currentView]();bindView();return}rc11BaseRenderContent()};
const rc11BaseBindView=bindView;
bindView=function(){rc11BaseBindView();rc11BindController()};
const rc11BaseRenderShell=renderShell;
renderShell=function(){rc11SyncNavDefinitions();const out=rc11BaseRenderShell();rc11EnhanceTopbar();rc11EnhanceCalculator();rc11EnhanceMessages();rc11TranslateLegacy($('content')||document.body);rc11ScheduleRefresh();return out};
const rc11BaseShowAuth=showAuth;showAuth=function(){rc11BaseShowAuth();rc11ApplyAuthLanguage();rc11TranslateLegacy($('authScreen')||document.body)};
rc11ApplyAuthLanguage();if(session&&currentAccount())renderShell();else showAuth();
